import XCTest
@testable import DrainspottingKit

/// The valid/wrong-SKU keys below were generated by running the ACTUAL
/// `issueLicenseKey` logic from alexcoulombepresents.com's
/// `lib/commerce/license.ts` (Node's `crypto.sign(null, body, privateKey)`
/// against this same test keypair) — not hand-crafted — so a pass here
/// proves real interop with the server side, not just self-consistency.
final class LicenseVerifierTests: XCTestCase {

    /// Test-only keypair, generated the same way as the real one
    /// (`scripts/generate-license-keypair.ts`) but never used for anything
    /// real. Never use these strings outside this test file.
    static let testPublicKeyPEM = """
    -----BEGIN PUBLIC KEY-----
    MCowBQYDK2VwAyEAZ/RVlKOFT7jzNQnWnZfWUfqdkpS21fdriDJp9TOIVqQ=
    -----END PUBLIC KEY-----
    """

    static let validKey =
        "eyJza3UiOiJkcmFpbnNwb3R0aW5nIiwidGllciI6ImluZGllIiwic2VhdHMiOjEsImxpY2Vuc2VlX2VtYWlsIjoidGVzdEBleGFtcGxlLmNvbSIsIm1ham9yX3ZlcnNpb24iOjEsInVwZGF0ZXNfdW50aWwiOiIyMDI3LTA3LTI5VDAwOjAwOjAwLjAwMFoiLCJpc3N1ZWRfYXQiOiIyMDI2LTA3LTI5VDAwOjAwOjAwLjAwMFoifQ.yPOBPLJENFdF-uvPJkAQLFZ4aUc_nDwZc8Y2x1rOykA8mRLOQHzl1D8G7J7vkd6L53jyKjH9xj-GskDBy29-CA"

    /// Same signer, same encoding, but payload sku is a different real ACP
    /// product ("mh-godot-pipeline") — validly signed, wrong product.
    static let wrongSKUKey =
        "eyJza3UiOiJtaC1nb2RvdC1waXBlbGluZSIsInRpZXIiOiJpbmRpZSIsInNlYXRzIjoxLCJsaWNlbnNlZV9lbWFpbCI6InRAZS5jb20iLCJtYWpvcl92ZXJzaW9uIjoxLCJ1cGRhdGVzX3VudGlsIjoiMjAyNy0wMS0wMVQwMDowMDowMC4wMDBaIiwiaXNzdWVkX2F0IjoiMjAyNi0wMS0wMVQwMDowMDowMC4wMDBaIn0.Nr3AII2a2hlbs7XkEtlOlQKXOpJkpYf4myNA_BSLN52WDFQjfSZErOESuMI2bIG84tylvv7qjO9KmU8hWTuiDw"

    func testValidKeyVerifiesAndDecodes() {
        let result = LicenseVerifier.verify(Self.validKey, publicKeyPEM: Self.testPublicKeyPEM)
        guard case .success(let payload) = result else {
            return XCTFail("expected success, got \(result)")
        }
        XCTAssertEqual(payload.sku, "drainspotting")
        XCTAssertEqual(payload.tier, "indie")
        XCTAssertEqual(payload.seats, 1)
        XCTAssertEqual(payload.licenseeEmail, "test@example.com")
        XCTAssertEqual(payload.majorVersion, 1)
        XCTAssertEqual(payload.updatesUntil, "2027-07-29T00:00:00.000Z")
    }

    func testWrongSKUIsRejectedEvenThoughSignatureIsValid() {
        let result = LicenseVerifier.verify(Self.wrongSKUKey, publicKeyPEM: Self.testPublicKeyPEM)
        guard case .failure(let error) = result else {
            return XCTFail("expected failure, got \(result)")
        }
        XCTAssertEqual(error, .wrongProduct(expected: "drainspotting", found: "mh-godot-pipeline"))
    }

    func testTamperedPayloadFailsSignatureCheck() {
        // Flip one character in the payload segment — same signature, different body.
        var parts = Self.validKey.split(separator: ".").map(String.init)
        var body = parts[0]
        let idx = body.index(body.startIndex, offsetBy: 5)
        body.replaceSubrange(idx...idx, with: body[idx] == "a" ? "b" : "a")
        parts[0] = body
        let tampered = parts.joined(separator: ".")

        let result = LicenseVerifier.verify(tampered, publicKeyPEM: Self.testPublicKeyPEM)
        guard case .failure(let error) = result else {
            return XCTFail("expected failure, got \(result)")
        }
        // Either the base64 no longer decodes cleanly or the signature no longer matches —
        // both are correct rejections; what must never happen is `.success`.
        XCTAssertTrue(error == .signatureMismatch || error == .badEncoding, "got \(error)")
    }

    func testTamperedSignatureFailsSignatureCheck() {
        var parts = Self.validKey.split(separator: ".").map(String.init)
        var sig = parts[1]
        let idx = sig.index(sig.startIndex, offsetBy: 5)
        sig.replaceSubrange(idx...idx, with: sig[idx] == "a" ? "b" : "a")
        parts[1] = sig
        let tampered = parts.joined(separator: ".")

        let result = LicenseVerifier.verify(tampered, publicKeyPEM: Self.testPublicKeyPEM)
        guard case .failure(let error) = result else {
            return XCTFail("expected failure, got \(result)")
        }
        XCTAssertTrue(error == .signatureMismatch || error == .badEncoding, "got \(error)")
    }

    func testMalformedKeyShapes() {
        XCTAssertEqual(LicenseVerifier.verify("", publicKeyPEM: Self.testPublicKeyPEM),
                       .failure(.malformedKey))
        XCTAssertEqual(LicenseVerifier.verify("no-dot-here", publicKeyPEM: Self.testPublicKeyPEM),
                       .failure(.malformedKey))
        XCTAssertEqual(LicenseVerifier.verify("a.b.c", publicKeyPEM: Self.testPublicKeyPEM),
                       .failure(.malformedKey))
        XCTAssertEqual(LicenseVerifier.verify("not-base64!!!.also-not-base64!!!", publicKeyPEM: Self.testPublicKeyPEM),
                       .failure(.badEncoding))
    }

    func testWrongPublicKeyRejectsAGenuineSignature() {
        // A different, unrelated Ed25519 public key (from `swift package
        // generate...` style throwaway) must not validate the real signature.
        let otherKeyPEM = """
        -----BEGIN PUBLIC KEY-----
        MCowBQYDK2VwAyEAUgkiJ9LRJT6OFqV9WhmLuMPZn7Nqj73pPQLPyHJNZYM=
        -----END PUBLIC KEY-----
        """
        let result = LicenseVerifier.verify(Self.validKey, publicKeyPEM: otherKeyPEM)
        // Either this random 32 bytes fails to parse as a valid Curve25519 key
        // (rare but possible) or the signature check correctly fails against it.
        guard case .failure(let error) = result else {
            return XCTFail("a signature from a different key must never verify")
        }
        XCTAssertTrue(error == .signatureMismatch || error == .invalidPublicKey, "got \(error)")
    }

    func testSPKIRawKeyExtractionMatchesKnownLayout() {
        // Verified independently via python: 44 bytes total, fixed 12-byte
        // RFC 8410 Ed25519 SPKI header, then the raw 32-byte public key.
        let raw = LicenseVerifier.rawPublicKey(fromPEM: Self.testPublicKeyPEM)
        XCTAssertEqual(raw?.count, 32)
        XCTAssertEqual(raw?.map { String(format: "%02x", $0) }.joined(),
                       "67f45594a3854fb8f33509d69d97d651fa9d9294b6d5f76b883269f5338856a4")
    }
}
